package com.oibsip.onlineexam.ui;
import com.oibsip.onlineexam.repository.*; import com.oibsip.onlineexam.service.*; import com.oibsip.onlineexam.session.*; import java.awt.*; import javax.swing.*;
public class MainFrame extends JFrame {public static final String LOGIN="LOGIN",PROFILE="PROFILE",EXAM="EXAM",RESULT="RESULT"; private final CardLayout cards=new CardLayout(); private final JPanel root=new JPanel(cards); private final SessionManager session=new SessionManager(); private final AuthenticationService auth=new AuthenticationService(new UserRepository()); private final ProfileService profile=new ProfileService(); private final ExamService exam=new ExamService(); private final QuestionRepository questions=new QuestionRepository(); public MainFrame(){setTitle("Online Examination System");setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);setMinimumSize(new Dimension(900,650));setSize(1050,720);setLocationRelativeTo(null);root.add(new LoginPanel(this),LOGIN);root.add(new ProfilePanel(this),PROFILE);root.add(new ExamPanel(this),EXAM);root.add(new ResultPanel(this),RESULT);setContentPane(root);addWindowListener(new java.awt.event.WindowAdapter(){public void windowClosing(java.awt.event.WindowEvent e){if(session.getExam()!=null&&!session.getExam().isSubmitted()){int x=JOptionPane.showConfirmDialog(MainFrame.this,"Are you sure you want to quit?\nYour current examination progress will be lost.","Confirm Exit",JOptionPane.YES_NO_OPTION);if(x==JOptionPane.YES_OPTION)System.exit(0);}else System.exit(0);}});} public void show(String c){if(c.equals(PROFILE))((ProfilePanel)root.getComponent(1)).refresh(); if(c.equals(EXAM))((ExamPanel)root.getComponent(2)).begin(); if(c.equals(RESULT))((ResultPanel)root.getComponent(3)).refresh();cards.show(root,c);} public SessionManager session(){return session;} public AuthenticationService auth(){return auth;} public ProfileService profile(){return profile;} public ExamService exam(){return exam;} public QuestionRepository questions(){return questions;} public void logout(){session.clear();show(LOGIN);} }
